-- [E2]

-- [5]

-- the installation marked before the list of settings as one of an earlier version keeps night processing of
-- documents; the mark goes right after, so a later seed never changes the value again (the administrator's choice stays;
-- the one exception is a choice made while an interrupted upgrade still holds the mark — the repeated deploy pins night)
UPDATE settings SET value = '"night"'::jsonb
 WHERE instance_id = :'instance' AND category = 'processing' AND key = 'documents_lane'
   AND EXISTS (SELECT 1 FROM maintenance_state WHERE instance_id = :'instance' AND key = 'documents_lane_pin');
DELETE FROM maintenance_state WHERE instance_id = :'instance' AND key = 'documents_lane_pin';
-- An installation seeded by an earlier version keeps an owner's agent adding space members (access.agent_member_add):
-- there the row is new (no default yet, the statement below sets it) while rows of an earlier run already have
-- one. A fresh installation keeps "workplace"; the default stays "workplace" on both; a later seed changes nothing here.
UPDATE settings SET value = '"allow"'::jsonb, default_value = '"workplace"'::jsonb, updated_at = now()
 WHERE instance_id = :'instance' AND category = 'access' AND key = 'agent_member_add' AND default_value IS NULL
   AND EXISTS (SELECT 1 FROM settings s WHERE s.instance_id = :'instance' AND s.default_value IS NOT NULL);
-- an installation of an earlier version that syncs directory groups less often than every 11 h 30 min gets an
-- expiry of two sync periods plus an hour instead of 24 hours (a shorter one would remove every group member after one
-- failed sync and is refused by the settings check); the row is new there (no default yet). The default stays 24; a later
-- seed changes nothing. ceil((2 × minutes + 60) / 60) by integer division only (the seed calls no functions beyond its short list).
UPDATE settings SET value = ((((SELECT (g.value #>> '{}')::numeric FROM settings g WHERE g.instance_id = :'instance' AND g.category = 'ldap' AND g.key = 'group_sync_minutes')::int * 2 + 119) / 60)::text)::jsonb, default_value = '24'::jsonb, updated_at = now()
 WHERE instance_id = :'instance' AND category = 'ldap' AND key = 'group_stale_hours' AND default_value IS NULL
   AND EXISTS (SELECT 1 FROM settings g WHERE g.instance_id = :'instance' AND g.category = 'ldap' AND g.key = 'group_sync_minutes' AND jsonb_typeof(g.value) = 'number' AND (g.value #>> '{}')::numeric > 690 AND (g.value #>> '{}')::numeric <= 1440);
UPDATE settings SET default_value = value WHERE instance_id = :'instance' AND default_value IS NULL AND NOT secret;
-- the default of processing.documents_lane is now, also where the pin above made night the value (the statement
-- above copied it into the default)
UPDATE settings SET default_value = '"now"'::jsonb
 WHERE instance_id = :'instance' AND category = 'processing' AND key = 'documents_lane' AND default_value IS DISTINCT FROM '"now"'::jsonb;
-- access.internal_networks has no seed default — unset means the default of the deploy profile (internalNetworksDefault).
-- The statement above copies a stored list into default_value on an upgraded database; put NULL back (the value stays)
UPDATE settings SET default_value = NULL
 WHERE instance_id = :'instance' AND category = 'access' AND key = 'internal_networks' AND default_value IS NOT NULL;
-- the default of locale.mcp_language is en
UPDATE settings SET default_value = '"en"'::jsonb
 WHERE instance_id = :'instance' AND category = 'locale' AND key = 'mcp_language' AND default_value IS DISTINCT FROM '"en"'::jsonb;
-- a custom rule of open_check.extra_rules saved by an earlier version under a name that a built-in rule took later
-- (cloud_key, high_entropy_secret, bank_account, national_id, phone_intl, date_of_birth) is renamed
-- <name>_custom when the list does not have that name, otherwise <name>_custom_<n> for the first free n of q, q + 1, q + 2
-- (q — the position in the list from 1, at least 2; all three taken — q + 2): the panel refuses to save a list with a taken
-- name, and the check reads what an author may show by the rule's name. Each statement sees the renames of the positions
-- before it; until this runs the check runs such a rule under the same new name, reading the list the same way
-- (extraRuleRunsAs, packages/shared/src/open-check.ts). The rule's pattern, kind and reason are kept; a re-run finds no such
-- name and changes nothing. One statement per position of the list (the panel keeps at most 100 rules): the seed's
-- statements call only plain built-ins.
UPDATE settings SET value = jsonb_set(value, '{0,name}', ('"' || (value->0->>'name') || '_custom' || coalesce((SELECT '' WHERE NOT value @> ('[{"name": "' || (value->0->>'name') || '_custom"}]')::jsonb), (SELECT '_2' WHERE NOT value @> ('[{"name": "' || (value->0->>'name') || '_custom_2"}]')::jsonb), (SELECT '_3' WHERE NOT value @> ('[{"name": "' || (value->0->>'name') || '_custom_3"}]')::jsonb), '_4') || '"')::jsonb), updated_at = now() WHERE instance_id = :'instance' AND category = 'open_check' AND key = 'extra_rules' AND jsonb_typeof(value->0) = 'object' AND value->0->>'name' IN ('cloud_key','high_entropy_secret','bank_account','national_id','phone_intl','date_of_birth');
