-- the defaults of the data-policy keys are the values of a new installation, also where the first seed of this
-- version wrote the permissions of an earlier version (the statement above copied them into the defaults): "reset to the
-- default" never restores a migrated permission
UPDATE settings SET default_value = '[]'::jsonb
 WHERE instance_id = :'instance' AND category = 'models' AND key IN ('allow_closed', 'allow_open') AND default_value IS DISTINCT FROM '[]'::jsonb;
UPDATE settings SET default_value = 'false'::jsonb
 WHERE instance_id = :'instance' AND category = 'models' AND key = 'health_strict' AND default_value IS DISTINCT FROM 'false'::jsonb;
UPDATE settings SET default_value = '"hourly"'::jsonb
 WHERE instance_id = :'instance' AND category = 'models' AND key = 'audit_calls' AND default_value IS DISTINCT FROM '"hourly"'::jsonb;
-- access.morning_note: the default is the value of a new installation (on), also where the first seed gave the note switched off
UPDATE settings SET default_value = '{"enabled":true,"time":"08:00","tz":null,"weekdays":[1,2,3,4,5]}'::jsonb
 WHERE instance_id = :'instance' AND category = 'access' AND key = 'morning_note' AND default_value IS DISTINCT FROM '{"enabled":true,"time":"08:00","tz":null,"weekdays":[1,2,3,4,5]}'::jsonb;
-- the default of access.mcp_output_schemas is open, also where the first seed of this version gave an earlier
-- installation strict (the statement above copied that value into the default)
UPDATE settings SET default_value = '"open"'::jsonb
 WHERE instance_id = :'instance' AND category = 'access' AND key = 'mcp_output_schemas' AND default_value IS DISTINCT FROM '"open"'::jsonb;
-- the default of access.mcp_tools_profile is core, also where the first seed of this version gave an earlier
-- installation full
UPDATE settings SET default_value = '"core"'::jsonb
 WHERE instance_id = :'instance' AND category = 'access' AND key = 'mcp_tools_profile' AND default_value IS DISTINCT FROM '"core"'::jsonb;
-- the default of access.mcp_response_detail is lean, also where the first seed of this version gave an earlier
-- installation full
UPDATE settings SET default_value = '"lean"'::jsonb
 WHERE instance_id = :'instance' AND category = 'access' AND key = 'mcp_response_detail' AND default_value IS DISTINCT FROM '"lean"'::jsonb;

-- No starting embedder: a fresh install searches by keyword until an embedding model is configured; the
-- registry row of an upgraded install stays as it is.

INSERT INTO never_open_rules (kind, pattern, reason, instance_id)
SELECT 'entity_kind', 'person', 'Personal data: information about employees', :'instance'
WHERE NOT EXISTS (SELECT 1 FROM never_open_rules WHERE kind = 'entity_kind' AND pattern = 'person' AND instance_id = :'instance');
